<script setup lang="ts">import{onMounted,ref,watch}from 'vue';import{samples,loadBatches,loadUnits}from '../stores/samples';import{createBatch,importUnits}from '../api/batches';import{canEdit}from '../stores/auth';import{useTask}from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import BatchSelect from '../components/BatchSelect.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import EmptyState from '../components/common/EmptyState.vue';const selected=ref(1),showCreate=ref(false),showImport=ref(false),message=ref('');const form=ref({code:'',name:'',description:''});const csv=ref(`code,zone,age_band,mode,trip_minutes,base_weight
IMPORT01,中心,青年,小汽车,25,1
IMPORT02,东区,中年,公交,41,1
IMPORT03,西区,长者,轨道,36,1`);const{error,busy,execute}=useTask();const refresh=()=>execute(async()=>{await loadBatches();await loadUnits(selected.value)});watch(selected,()=>execute(()=>loadUnits(selected.value)));const save=()=>execute(async()=>{const b=await createBatch(form.value);await loadBatches();selected.value=b.id;showCreate.value=false;message.value='批次已建立，可导入匿名样本。'});const importing=()=>execute(async()=>{const r=await importUnits(selected.value,csv.value);message.value='已导入'+r.imported+'条样本；已有记录未覆盖。';showImport.value=false;await loadBatches();await loadUnits(selected.value)});onMounted(refresh);</script><template><PageHeading index="02" title="匿名样本底册" subtitle="保留来源与初始权重，目标边际与样本值分别登记。"/><ErrorNotice :message="error" @retry="refresh"/><p v-if="message" class="success">{{message}}</p><div class="toolbar"><BatchSelect v-model="selected" :items="samples.batches"/><div v-if="canEdit"><button @click="showCreate=!showCreate">＋ 新批次</button><button @click="showImport=!showImport">导入 CSV 文本</button></div></div><form v-if="showCreate" class="form-strip" @submit.prevent="save"><label>批次编码<input v-model="form.code" required pattern="[a-z0-9-]+"/></label><label>批次名称<input v-model="form.name" required minlength="2"/></label><label class="grow">说明<input v-model="form.description" maxlength="500"/></label><button class="primary" :disabled="busy">保存批次</button></form><form v-if="showImport" class="import-form" @submit.prevent="importing"><label>CSV 文本<textarea v-model="csv" rows="7" required/></label><p>列：code, zone, age_band, mode, trip_minutes, base_weight；整批验证后写入，最多5000行。</p><button class="primary" :disabled="busy">校验并导入</button></form><div class="source-note"><span>{{samples.batches.find(b=>b.id===selected)?.source_file}}</span><span>{{samples.units.length}}条 · 当前展示前100条</span></div><EmptyState v-if="!samples.units.length" title="还没有样本" hint="建立批次后导入CSV，至少包含全部正目标类别的样本支持。"/><div class="table-wrap" v-else><table><thead><tr><th>匿名编号</th><th>居住分区</th><th>年龄组</th><th>出行方式</th><th>出行时长 / 分钟</th><th>初始权重</th></tr></thead><tbody><tr v-for="u in samples.units.slice(0,100)" :key="u.id"><td class="mono">{{u.code}}</td><td>{{u.zone}}</td><td>{{u.age_band}}</td><td>{{u.mode}}</td><td>{{u.trip_minutes}}</td><td>{{u.base_weight}}</td></tr></tbody></table></div></template>
